def _groups(active):
    groups=[]
    for r in active:
        if not groups or r>groups[-1][-1]+1: groups.append([r])
        else: groups[-1].append(r)
    return groups

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    groups=_groups([r for r,row in enumerate(grid) if any(v!=bg for v in row)])
    if len(groups)<2: return [row[:] for row in grid]
    # Pick the two active bands with closest row count, prefer topmost pair.
    pairs=[(i,j) for i in range(len(groups)) for j in range(i+1,len(groups)) if len(groups[i])==len(groups[j])]
    if not pairs: return [row[:] for row in grid]
    i,j=min(pairs,key=lambda p:(p[1]-p[0],p[0]))
    g1,g2=groups[i],groups[j]
    n=len(g1)
    # Estimate horizontal translation of band 1 into band 2.
    best=None
    for d in range(-w+1,w):
        agree=total=0
        for arow,brow in zip(g1,g2):
            for c in range(w):
                ac=c-d
                if 0<=ac<w:
                    av=grid[arow][ac]!=bg
                    bv=grid[brow][c]!=bg
                    total+=1
                    agree += (av==bv)
        # Compare only overlapping columns; slight preference for smaller shifts.
        score=agree/total if total else -1
        key=(score,-abs(d))
        if best is None or key>best[0]: best=(key,d)
    d=best[1]
    # Count the directional missing pixels after alignment.
    a_missing=[]; b_missing=[]; a_extra=[]; b_extra=[]
    for ra,rb in zip(g1,g2):
        for c2 in range(w):
            c1=c2-d
            if 0<=c1<w:
                fa=grid[ra][c1]!=bg
                fb=grid[rb][c2]!=bg
                if not fa and fb: a_missing.append((ra,c1))
                if fa and not fb: b_missing.append((rb,c2))
    out=[row[:] for row in grid]
    if len(a_missing)>len(b_missing):
        for r,c in a_missing: out[r][c]=1
    elif len(b_missing)>len(a_missing):
        for r,c in b_missing: out[r][c]=1
    return out
